   "o": [],
   "c": -1,
   "why": "1- الجهاز التناسلي الذكري للحشرات: خصيتان تقعان فوق القناة الهضمية أو على جانبها. الجهاز التناسلي الذكري لدودة الأرض: زوجان من الخصى الصغيرة يقعان في الحلقتين 10، 11. 2- الجهاز التناسلي الذكري للحشرات: زوجان من الأجسام المنوية يقعان قرب كل خصية. الجهاز التناسلي الذكري لدودة الأرض: لا يحتوي على أقماع منوية. 3- الجهاز التناسلي الذكري للحشرات: زوج من الأقنية الناقلة للحيامن تمتد إلى الحلقة 15. الجهاز التناسلي الذكري لدودة الأرض: زوج من الأقنية الناقلة للحيامن التي تتصل من مقدمتها بالخصية ومن مؤخرتها بالحوصلة المنوية. 4- الجهاز التناسلي الذكري للحشرات: تحاط الخصية والأجسام المنوية والأقنية للحيامن لكل جانب بثلاثة حويصلات منوية (يكون المجموع ثلاثة أزواج من الحويصلات المنوية للجانبين). الجهاز التناسلي الذكري لدودة الأرض: حويصلتان منويتان تمثل كل منهما منطقة متسعة من القناة الناقلة في كل جانب. 5- الجهاز التناسلي الذكري للحشرات: لا توجد قناة قاذفة. الجهاز التناسلي الذكري لدودة الأرض: تتحد القناتان الناقلتان للحيامن لتكون القناة القاذفة. 6- الجهاز التناسلي الذكري للحشرات: لا يحتوي على قضيب. الجهاز التناسلي الذكري لدودة الأرض: يوجد قضيب يمثل امتداداً للقناة القاذفة. 7- الجهاز التناسلي الذكري للحشرات: زوج من الفتحات التناسلية على جانبي السطح البطني للحلقة 15. الجهاز التناسلي الذكري لدودة الأر",
