   "q": "يرمز للأليل المسؤول عن العامل الريسي الموجب بالرمز Rh، ويرمز للأليل المسؤول عن العامل الريسي السالب بالرمز rh. استنتج وراثياً حالة رجل ذو Rh وامرأة ذات Rh (علماً أن والد الرجل ذو rh ووالد المرأة ذو rh)، وما هي احتمالية إصابة الأولاد بمرض اليرقان؟",
   "o": [],
