   "why": "1- الجسيم المركزي: له دور مهم في تكوين الجسيمات التي يتم فيها تكوين البروتينات. 2- الجسم الطرفي: تكوين مواد ذات طبيعة إنزيمية تعمل على تحلل أغشية البيضة عند التقاء النطفة بالبيضة لغرض تسهيل مرور النطفة إلى سطح البيضة. 3- دكتيوسوم (جهاز كولجي): تشكل مراكز لتحول سكر الكلوكوز إلى سكريات متعددة مثل النشاء أو إلى الكلوكوز وبروتينات. 4- دكتيوسوم (بناء السليلوز): يقوم ببناء السليلوز وبعض مكونات الجدار الخلوي. 5- النسيج الكولنكيمي: وظيفة الدعم والتقوية.",
