   "c": -1,
   "why": "1- اللمف: سائل يتجمع من الأنسجة ويرجع للمجرى الدموي بواسطة أوعية لمفاوية. البلازما: سائل يمكن الحصول عليه بترشيح الدم ويكون بلون أصفر فاتح ويمثل المادة البينية لنسيج الدم وهو نسيج ضام متخصص. 2- اللمف: يشبه البلازما في التركيب إلا أن محتواه البروتيني أقل. البلازما: يتركب من 90% ماء و10% مواد صلبة مثل البروتينات والهرمونات والإنزيمات وأملاح لا عضوية وكلوكوز. 3- اللمف: عملية التخثر أبطأ. البلازما: عملية التخثر أسرع. 4- اللمف: الخثرة تكون لينة. البلازما: الخثرة تكون صلبة. 5- اللمف: يحتوي على خلايا لمفية بالدرجة الرئيسية. البلازما: لا يحتوي. (ملاحظة: يكتفى بذكر ثلاث نقاط فقط).",
