   "q": "قارن بين التخمر الكحولي والتخمر اللبني",
   "o": [],
   "c": -1,
   "why": "التخمر الكحولي: 1- يحصل في الخميرة والنباتات عند غياب الأوكسجين أو نقصه وفي بعض أنواع البكتريا. 2- يحصل أكسدة للحامض البايروفي بنزع CO2 محولاً إياه إلى أسيتالديهايد. 3- يتم اختزال الأسيتالديهايد بواسطة الهايدروجين الناتج من التحلل السكري. 4- نواتجه كحول أثيلي + 2ATP. 5- تنفس لاهوائي يحدث عند غياب أو نقص الأوكسجين. التخمر اللبني: 1- يحصل في بعض أنواع البكتريا والعضلات. 2- لا يحصل أكسدة للحامض البايروفي وإنما اختزال. 3- يتم اختزال الحامض البايروفي بواسطة الهايدروجين الناتج من التحلل السكري. 4- نواتجه حامض لبني + 2ATP. 5- تنفس لاهوائي يحدث كذلك عند غياب أو نقص الأوكسجين.",
