   "c": -1,
   "why": "1. قناتي فالوب: وهما انبوبتان لحمل البيض نهايتهما الامامية لها فتحات قمعية الشكل تستقبل البيض الذي يتحرر من المبيض بعد عملية التبويض وقناة البيض ذات بطانة مهدبة لدفع البيض في مسيرته وتفتح قناتا البيض في الجانبين العلويين للرحم، وتدعى أيضاً قناتي البيض. 2. الدبق العصبي: وهي خلايا تشكل القسم الاعظم من النسيج العصبي حيث تكون نسبتها ضمن النسيج العصبي (50:1) أي كل عصبونة يقابلها (50) من خلايا الدبق العصبي وهي تشغل اكثر من نصف حجم الدماغ وتتلخص وظيفتها باسناد الخلايا العصبية فضلاً عن كونها تبتلع البكتريا والفتات الخلوي.",
