   "o": [],
   "c": -1,
   "why": "هو الطور الذي يسبق الأطوار الأربعة من الانقسام حيث تمر الخلية بهذا الطور قبل بدء عملية انقسام الخلية، ويلاحظ فيه أن نواة الخلية تكون كبيرة بالمقارنة مع الأنوية في الخلايا المنقسمة، وتقوم الخلية في هذا الطور بتخليق جزيئات كبيرة من الأحماض النووية والبروتينات كخطوة تحضيرية لعملية الانقسام، وأهم ما يتميز به هذا الطور هو تضاعف جزيئات الحامض النووي الرايبي ناقص الأوكسجين (DNA) كما يتضاعف الجسيم المركزي.",
