   "o": [],
   "c": -1,
   "why": "1- شكل الليف العضلي: الهيكلية (اسطواني طويل غير متفرع)، القلبية (اسطواني متفرع أقصر من ليف العضلة الهيكلية). 2- حجم الليف: الهيكلية (كبير وطويل)، القلبية (أصغر من ليف العضلة الهيكلية). 3- النواة: الهيكلية (متعددة الأنوية ومحيطية الموقع)، القلبية (مفردة مركزية الموقع). 4- الفعل: الهيكلية (إرادي)، القلبية (لا إرادي). 5- الأقراص البينية: الهيكلية (لا توجد)، القلبية (توجد). 6- الوظيفة/الموقع: الهيكلية (ترتبط مع العظام بواسطة أوتار وعند تقلصها يتحرك جزء الجسم الموجودة فيه)، القلبية (توجد في جدران القلب فقط وتقلصها يضخ الدم من القلب وتمددها يسمح بدخول الدم إلى القلب). 7- الغشاء: الهيكلية (تحاط بغشاء خاص يدعى الساركوليما)، القلبية (غشاؤها أرق). 8- التخطيط: الهيكلية (منتظمة وذات خطوط مستعرضة تظهر فيها مناطق غامقة وفاتحة)، القلبية (منتظمة وذات خطوط مستعرضة تظهر فيها مناطق غامقة وفاتحة).",
