   "q": "ما التغيرات التي تطرأ على الخلية في الطور التمهيدي للانقسام الخيطي؟",
   "o": [],
   "c": -1,
   "why": "1. تتميز في هذا الطور الشبكة الكروماتينية إلى عدد من الكروموسومات. 2. تبدو الكروموسومات كثيفة وتتميز إلى جزئين متماثلين تماماً (كروماتيدين). 3. يرتبط هذان الكروماتيدان الشقيقان مع بعضهما عند منطقة جزئيهما المركزيين واللذان يكونان الكروموسومات البنوية. 4. تتباعد الجسمان المركزيان اللذان سبق وأن تكونا في الطور البيني ويتجهان في اتجاهين متعاكسين نحو قطبي الخلية. 5. تمتد من كل منهما خيوط شعاعية (النجم). 6. تتكون خيوط المغزل. 7. يختفي الغشاء النووي في مرحلة متأخرة من هذا الطور. (ملاحظة: يكتفي الطالب بست نقاط فقط).",
