   "o": [],
   "c": -1,
   "why": "1- المايتوكوندريا: تراكيب كروية أو خيطية بأشكال وأحجام مختلفة، عرضها (0.5-1) مايكرومتر وطولها قد يصل إلى (10) مايكرومتر. البلاستيدة الخضراء: تراكيب بيضوية أو كأسيّة أو قرصية الشكل. 2- المايتوكوندريا: توجد في سايتوبلازم جميع الخلايا حقيقية النواة. البلاستيدة الخضراء: توجد في سايتوبلازم الخلايا النباتية. 3- المايتوكوندريا: وظيفتها التنفس الخلوي التي يتم فيها إنتاج طاقة. البلاستيدة الخضراء: وظيفتها البناء الضوئي التي يتم فيها استهلاك طاقة. 4- المايتوكوندريا: تحتوي على إنزيمات تنفسية. البلاستيدة الخضراء: تحتوي على صبغات خضراء وصبغات أخرى مساعدة. 5- المايتوكوندريا: تحاط بغشاء مزدوج والطبقة الداخلية منه تكون الأعراف. البلاستيدة الخضراء: تحاط بغشاء مزدوج ويوجد داخل الغشاء تركيبان هما البذيرة أو الكرانيوم والسدى أو القالب.",
