   "why": "١- الطور البيني :- وهو لطور تحربه الخلية قبل بدء عملية الانقسام ويلاحظ فيه ان النواة تكون كبيرة مقارنة مع الانوية في الخلايا المنقسمة وتقوم الخلية في هذا الطور بتخليق جزيئات كبيرة من الاحماض النووية والبروتينات كخطوة تحضيرية لعملية الانقسام وأهم ما يتميز به هذا الطور هو تضاعف جزيئات الحامض النووي الرايبي منقوص الاوكسجين DNA كما يتضاعف الجسيم المركزي في هذا الطور. ٢- الناضح :- هو حركة جزيئات الماء خلال فشاء أختياري النفاذية ( الغشاء البلازمي) تبعاً لاختلاف التركيز وتتم حركة جزيئات الماء وفق قانون الانتشار أذان التناضح هو حالة من عالات الانتشار. ٣- قنوات فوككمان :- وهي منوات مستعرضة توجدني العظم المصمت وتربط قنوات هاڤرس مع بعضها.",
