   "why": "الخلايا الجذعية الجنينية: 1- هي نوع أساسي في أنواع الخلايا الجذعية. 2- يمكن الحصول عليها في المراحل الجنينية المبكرة بعد الإخصاب. 3- تؤخذ من المراحل الجنينية وسهلة العزل. 4- لا يحصل فيها تقليل للعدد مع تقدم العمر. 5- قد تكون مسرطنة. 6- ذات قدرة عالية على التخصص لأنواع من الخلايا. 7- وظيفتها إصلاح واستبدال الخلايا التالفة عند زراعتها في العضو المصاب. الخلايا الجذعية البالغة: 1- هي نوع آخر في الخلايا الجذعية. 2- توجد مع الخلايا المتخصصة في الجسم. 3- توجد بكمية قليلة مما يؤدي إلى صعوبة عزلها. 4- يقل عددها مع تقدم العمر. 5- سليمة غالباً. 6- ليس لها نفس القدرة في التخصص. 7- وظيفتها استبدال الخلايا وتعويض الخلايا المتضررة أو الميتة في العضو.",
