   "why": "1- العاثيات: وهي أشباه بسيطة التركيب تصيب البكتيريا وتحللها أو تبقها خاملة، تحتوي على أشرطة DNA مزدوجة أو مفردة أو قد تحتوي على RNA مفرد، مثال على ذلك العاثي لامبدا (وهي أحد النواقل التي تلعب دوراً رئيسياً في تقنية الهندسة الوراثية). 2- السدى: هو المادة السائلة الشفافة التي تملأ الفسحة الداخلية للبلاستيدة وتحوي داخلها الكرانا التي تحوي الكلوروفيل وتوجد فيها الإنزيمات التي تختزل CO2 والذي يسهل على البلاستيدات الخضر القيام بعملية البناء الضوئي. 3- نمو الخلايا المفردة: وهو نوع نادر الحدوث حيث يحصل فيه نمو في حجم الخلايا ومثال على ذلك نمو الخلايا العصبية حيث أنها تزداد في الحجم أضعاف حجمها الأصلي ويرجع ذلك إلى زيادة حجم السايتوبلازم عن طريق تكوين عضيات جديدة وكذلك نمو التشجرات في الخلية العصبية الذي يزيد من المساحة السطحية للخلية وهو أحد طرق نمو الخلايا.",
