   "why": "أولاً الصفيحات الدموية: 1- خلايا مغزلية الشكل. 2- صغيرة الحجم (قطرها 2-4 ميكرون). 3- توجد في دم الشريات الأوطأ في سلم التطور. 4- عديمة اللون وخالية من النواة. 5- وظيفة الصفيحات الدموية هو تحرر إنزيم الثرومبوبلاستين الذي يلعب دوراً في تخثر الدم، وتحتوي على السيروتونين الذي يساعد في تقلص الأوعية الدموية. ثانياً الخلايا الخثرية: 1- أقراص كروية أو بيضوية. 2- أكبر حجماً من الصفيحات الدموية. 3- توجد في دم الفقريات مثل الطيور والبرمائيات. 4- تحتوي على نواة. 5- يعتقد أنها تشابه الصفيحات الدموية في وظيفتها.",
